INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'seamark-freight-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Seamark Freight in Khalifa Bin Salman Port.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من سيمارك للشحن في Khalifa Bin Salman Port.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution. Focusing on Import/Export Customs Clearance, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج. من خلال خدمة التخليص الجمركي للاستيراد والتصدير نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution.</p><p>Focusing on <strong>Import/Export Customs Clearance</strong>, our Khalifa Bin Salman Port specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج.</p><p>من خلال خدمة <strong>التخليص الجمركي للاستيراد والتصدير</strong>، يعمل فريقنا في Khalifa Bin Salman Port على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Seamark Freight', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | سيمارك للشحن', 'Executive guide by Seamark Freight covering Import/Export Customs Clearance benchmarks in Bahrain.', 'دليل تنفيذي من سيمارك للشحن حول معايير التخليص الجمركي للاستيراد والتصدير في البحرين.', 'Sustainability', '{"logistics","sustainability","Khalifa Bin Salman Port","2026"}'::text[], 'Hana Yousef', 'draft', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', false, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
