INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('8fd6dfdd-ef64-4587-a65b-b56d27e5813a', 'Eng. Salman Al-Moayyed', 'م. سلمان المؤيد', 'Almoayyed Contracting Group W.L.L.', 'مجموعة المؤيد للمقاولات ذ.م.م', 'Seamark Freight consistently delivers on complex Bahrain commercial schedules with transparent VAT documentation and responsive bilingual account leads.', 'تلتزم سيمارك للشحن دائماً بالجداول الزمنية للمشاريع التجارية في البحرين مع توثيق ضريبي شفاف وفريق حسابات سريع الاستجابة.', 5, true, 20, 2026, now() - interval '15 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('edc72fd8-f025-4ef8-af30-48d805f90908', 'Dr. Hessa Al-Zayani', 'د. حصة الزياني', 'Dilmunia Health & Wellness Center', 'مركز دلمونيا للصحة والعافية', 'From initial quotation to final commissioning, the Seamark Freight operations team exceeded our SLA expectations.', 'من عرض السعر الأولي حتى التسليم النهائي، تجاوز فريق عمليات سيمارك للشحن توقعاتنا في الالتزام بمستوى الخدمة.', 5, true, 21, 2026, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('d1129098-1b92-4d62-aa9c-fbf955f41a08', 'Are all Seamark Freight invoices compliant with Bahrain NBR 10% VAT regulations?', 'هل جميع فواتير سيمارك للشحن متوافقة مع لوائح ضريبة القيمة المضافة 10% في البحرين؟', 'Yes. Every quotation and tax invoice includes our registered VAT ID (200011432000002), itemized tax calculations, and verifiable QR metadata.', 'نعم، تتضمن كل فاتورة ضريبية وعرض سعر رقمنا الضريبي المسجل (200011432000002) مع تفصيل الضريبة ورمز التحقق.', 'billing', true, 20, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('618e9a66-d50c-4e84-a247-3f3a9fa71dd6', 'Which Bahrain governorates and GCC destinations do you cover?', 'ما هي المحافظات في البحرين ووجهات الخليج التي تغطونها؟', 'We provide same-day and next-day fulfillment across Capital, Muharraq, Northern, and Southern Governorates, plus scheduled cross-border freight to Saudi Arabia, UAE, Qatar, Kuwait, and Oman.', 'نوفر التوصيل في نفس اليوم أو اليوم التالي في جميع محافظات البحرين، بالإضافة إلى الشحن المجدول لدول مجلس التعاون الخليجي.', 'logistics', true, 21, now() - interval '23 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.page (id, slug, page_type, title_en, title_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, blocks, is_visible, in_header, in_footer, sort_order, created_at, updated_at) VALUES ('pg-home', 'home', 'home', 'Seamark Freight', 'سيمارك للشحن', 'Seamark Freight | Sea-Air Freight Forwarding, Bonded Warehousing & Customs', 'سيمارك للشحن | الشحن البحري والجوي والتخزين الجمركي والتخليص', 'B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution. Explore Seamark Freight in Khalifa Bin Salman Port.', 'شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج. تصفح صفحة سيمارك للشحن.', '[{"id":"pg-home-hero","type":"hero","titleEn":"Seamark Freight | Sea-Air Freight Forwarding, Bonded Warehousing & Customs","titleAr":"سيمارك للشحن | الشحن البحري والجوي والتخزين الجمركي والتخليص","image":"/api/files/media/banners/banner-01.png"},{"id":"pg-home-body","type":"rich_section","ctaEn":"Request Proposal","ctaAr":"طلب عرض سعر","sortOrder":1}]'::jsonb, false, false, false, 1, now() - interval '2160 hours', now()) ON CONFLICT (id) DO NOTHING;
